// start.kfx: kayak-fx26's `main` (C111): the REPL, live or plain
// (`kayak-fx26` or `kayak-fx26 repl`, its history's file given by the Rust
// as `--history FILE`, since FX-26 reads no environment), a scripted
// session (`--keys FILE`), or the engine run on files (`engine-main`).
pub fn history_of(mut r#as: Strings) -> Str {
    loop {
        if (null_p(r#as) || null_p(cdr(r#as))) {
            return str_lit("");
        } else if string_eq_p(car(r#as), str_lit("--history")) {
            return car(cdr(r#as));
        } else {
            r#as = cdr(r#as);
            continue;
        }
    }
}

// `kayak-fx26 --check FILE ...` (TODO §30): what `fixpt check` writes of a
// program, to compare the checkers form by form
// (`scripts/compare-checkers.py`): each definition's line, `define NAME :
// TYPE ! EFFECT` (a datatype's constructors too), each expression's,
// `TYPE ! EFFECT`. A refusal fails, as the checker does, with its message.
/// `body` inside the `poly` binders written in `w`, a definition's type,
/// nested as written (the checker's schemes keep binders' names only).
pub fn poly_wrapped(w: &'static Sexp, body: Str) -> Str {
    if (head_is_p(w, str_lit("poly")) && i64_eq(size(items(w)), 3i64) && not(has_prefix_p(body, str_lit("(poly ")))) {
        string_append(str_lit("(poly "), string_append(show_sexp(second(items(w))), string_append(str_lit(" "), string_append(poly_wrapped(third(items(w)), body), str_lit(")")))))
    } else {
        body
    }
}

pub fn written_body(mut w: &'static Sexp) -> &'static Sexp {
    loop {
        if (head_is_p(w, str_lit("poly")) && i64_eq(size(items(w)), 3i64)) {
            w = third(items(w));
            continue;
        } else {
            return w;
        }
    }
}

pub fn written_binders(v: &'static Cv, w: &'static Sexp) -> Strings {
    if (head_is_p(w, str_lit("poly")) && i64_eq(size(items(w)), 3i64)) {
        onto(poly_binders(v, w, false), written_binders(v, third(items(w))))
    } else {
        nil::<Str>()
    }
}

pub fn written_mentions_p(e: &'static Sexp, names: Strings) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            string_member_p(n, names)
        }
        Sexp::Lst(xs, f, l, p) => {
            any_p(lambda1s(move |x: &'static Sexp| {
                written_mentions_p(x, names)
            }), xs)
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

// Abbreviations by name (C164): a definition's type is the checker's,
// printed, each abbreviation its written type names put back where the
// abbreviation's expansion is printed (one of a parenthesized type only).
pub enum Abbrev {
    Abbrev(Str, Str),
}

pub fn abbrev(f0: Str, f1: Str) -> &'static Abbrev {
    kayak_rt::heap_alloc(Abbrev::Abbrev(f0, f1))
}

pub type Abbrevs = List<&'static Abbrev>;

/// `t`, each abbreviation kept by name (`named-as`) its expansion.
pub fn unnamed(mut t: &'static Ty) -> &'static Ty {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                if has_prefix_p(d, str_lit("%named ")) {
                    t = car(args);
                    continue;
                } else {
                    return ty_data(d, map(&unnamed, args));
                }
            }
            Ty::TyList(e, r) => {
                return ty_list(unnamed(e), unnamed(r));
            }
            Ty::TyRef(e, r) => {
                return ty_ref(unnamed(e), unnamed(r));
            }
            Ty::TyFlat(e, r) => {
                return ty_flat(unnamed(e), unnamed(r));
            }
            Ty::TyProc(es, ps, r) => {
                return ty_proc(es, map(&unnamed, ps), unnamed(r));
            }
            Ty::TyShape(p, ls, ts) => {
                return ty_shape(p, ls, map(&unnamed, ts));
            }
            Ty::TyTag(a, h, es, r) => {
                return ty_tag(unnamed(a), unnamed(h), es, unnamed(r));
            }
            _ => {
                let other = tagcase_;
                return t;
            }
        }
    }
}

pub fn abbrevs_in(mut t: &'static Ty) -> Abbrevs {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Ty::TyData(d, args) => {
                if has_prefix_p(d, str_lit("%named ")) {
                    let (name, expansion) = (if null_p(cdr(args)) {
                        after_prefix(d, str_lit("%named "))
                    } else {
                        string_append(str_lit("("), string_append(after_prefix(d, str_lit("%named ")), string_append(str_lit(" "), string_append(show_tys(new_state(), map(&unnamed, cdr(args))), str_lit(")")))))
                    }, show_ty(new_state(), unnamed(car(args))));
                    if has_prefix_p(expansion, str_lit("(")) {
                        return the::<Abbrevs>(kayak_rt::heap_cons(abbrev(expansion, name), kayak_rt::nil()));
                    } else {
                        return nil::<&'static Abbrev>();
                    }
                } else {
                    return concat(map(&abbrevs_in, args));
                }
            }
            Ty::TyList(e, r) => {
                t = e;
                continue;
            }
            Ty::TyRef(e, r) => {
                t = e;
                continue;
            }
            Ty::TyFlat(e, r) => {
                t = e;
                continue;
            }
            Ty::TyProc(es, ps, r) => {
                return onto(concat(map(&abbrevs_in, ps)), abbrevs_in(r));
            }
            Ty::TyShape(p, ls, ts) => {
                return concat(map(&abbrevs_in, ts));
            }
            Ty::TyTag(a, h, es, r) => {
                return onto(abbrevs_in(a), abbrevs_in(h));
            }
            _ => {
                let other = tagcase_;
                return nil::<&'static Abbrev>();
            }
        }
    }
}

/// `cs` with each `from` replaced by `to`, onto `acc` reversed.
pub fn chars_replaced(mut cs: Chars, mut from: Chars, mut to: Chars, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return reverse(acc);
        } else if chars_start_p(cs, from) {
            (cs, acc) = (chars_after(cs, from), onto(reverse(to), acc));
            continue;
        } else {
            (cs, acc) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc));
            continue;
        }
    }
}

pub fn chars_start_p(mut cs: Chars, mut p: Chars) -> bool {
    loop {
        if null_p(p) {
            return true;
        } else if null_p(cs) {
            return false;
        } else if char_eq_p(car(cs), car(p)) {
            (cs, p) = (cdr(cs), cdr(p));
            continue;
        } else {
            return false;
        }
    }
}

pub fn chars_after(mut cs: Chars, mut p: Chars) -> Chars {
    loop {
        if null_p(p) {
            return cs;
        } else {
            (cs, p) = (cdr(cs), cdr(p));
            continue;
        }
    }
}

/// `shown` with each abbreviation's name for its expansion, the longest
/// expansions first.
pub fn abbrevs_put(mut shown: Str, mut r#as: Abbrevs) -> Str {
    loop {
        if null_p(r#as) {
            return shown;
        } else {
            let longest = longest_abbrev(cdr(r#as), car(r#as));
            let rest = filter(lambda1s(move |a: &'static Abbrev| {
                not({
                    let tagcase_ = a;
                    match *tagcase_ {
                        Abbrev::Abbrev(e, n) => {
                            let tagcase_ = longest;
                            match *tagcase_ {
                                Abbrev::Abbrev(e2, n2) => {
                                    string_eq_p(e, e2)
                                }
                            }
                        }
                    }
                })
            }), r#as);
            let tagcase_ = longest;
            match *tagcase_ {
                Abbrev::Abbrev(e, n) => {
                    (shown, r#as) = (list_to_string(chars_replaced(string_chars(shown), string_chars(e), string_chars(n), nil::<char>())), rest);
                    continue;
                }
            }
        }
    }
}

pub fn longest_abbrev(mut r#as: Abbrevs, mut best: &'static Abbrev) -> &'static Abbrev {
    loop {
        if null_p(r#as) {
            return best;
        } else if {
            let tagcase_ = car(r#as);
            match *tagcase_ {
                Abbrev::Abbrev(e, n) => {
                    let tagcase_ = best;
                    match *tagcase_ {
                        Abbrev::Abbrev(e2, n2) => {
                            i64_gt(string_length_i64(e), string_length_i64(e2))
                        }
                    }
                }
            }
        } {
            (r#as, best) = (cdr(r#as), car(r#as));
            continue;
        } else {
            r#as = cdr(r#as);
            continue;
        }
    }
}

/// Binders in scope as the checker has them, a region's as a place's too
/// (C34).
pub fn written_tvars(bs: Strings) -> Strings {
    onto(bs, concat(map(lambda1s(move |b: Str| {
        if has_prefix_p(b, str_lit("'")) {
            the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%place "), b), kayak_rt::nil()))
        } else {
            nil::<Str>()
        }
    }), bs)))
}

/// A definition's type as printed: the checker's, each abbreviation its
/// written type names by name (C164).
pub fn written_shown(v: &'static Cv, written: &'static Sexp, t: &'static Ty) -> Str {
    if ({
        let tagcase_ = written;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                null_p(xs)
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } || written_mentions_p(written, kayak_rt::heap_cons(str_lit("%found"), kayak_rt::heap_cons(str_lit("->*"), kayak_rt::nil())))) {
        show_ty(new_state(), t)
    } else {
        abbrevs_put(show_ty(new_state(), t), abbrevs_in(parse_type(v, kayak_rt::heap_cons(str_lit("%keep-names"), written_tvars(written_binders(v, written))), written_body(written))))
    }
}

/// A definition's line: its name, its type as the checker has it, inside
/// its written binders, and the effect of making its value.
pub fn bound_line(v: &'static Cv, n: Str, written: &'static Sexp, effect: Str) -> Str {
    let found = find_bind(n, cv_binds(v));
    if null_p(found) {
        string_append(str_lit("define "), n)
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n2, sc, w) => {
                let tagcase_ = sc;
                match *tagcase_ {
                    Scheme::Scheme(tvars, t) => {
                        string_append(str_lit("define "), string_append(n, string_append(str_lit(" : "), string_append(poly_wrapped(written, written_shown(v, written, t)), string_append(str_lit(" ! "), effect)))))
                    }
                }
            }
        }
    }
}

pub fn no_form() -> &'static Sexp {
    lst(nil::<&'static Sexp>(), str_lit(""), 0i64, 0i64)
}

/// The effect of evaluating `n`'s value `e`, checked against its type as
/// the checker checks a constant's: none for a procedure.
pub fn value_effect(v: &'static Cv, n: Str, e: &'static Sexp) -> Str {
    let found = find_bind(n, cv_binds(v));
    if (null_p(found) || lambda_form_p(e)) {
        str_lit("pure")
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n2, sc, w) => {
                let tagcase_ = sc;
                match *tagcase_ {
                    Scheme::Scheme(tvars, t) => {
                        if null_p(tvars) {
                            let tagcase_ = expressions::check(at(v, str_lit("a definition's value"), nil::<Str>()), new_state(), e, t);
                            match *tagcase_ {
                                Res::Res(u, es, s) => {
                                    show_effs(es)
                                }
                            }
                        } else {
                            str_lit("pure")
                        }
                    }
                }
            }
        }
    }
}

/// The type written for global `n` among the program's `forms`, if one is.
pub fn written_of(mut n: Str, mut forms: Sexps) -> Sexps {
    loop {
        if null_p(forms) {
            return nil::<&'static Sexp>();
        } else {
            let f = car(forms);
            if ((head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*"))) && i64_eq(size(items(f)), 4i64) && {
                let tagcase_ = second(items(f));
                match *tagcase_ {
                    Sexp::Sym(m, f2, p2) => {
                        string_eq_p(m, n)
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                return the::<Sexps>(kayak_rt::heap_cons(third(items(f)), kayak_rt::nil()));
            } else {
                forms = cdr(forms);
                continue;
            }
        }
    }
}

/// An expression's type as printed: a call's, each abbreviation its
/// callee's written type names by name (C164), as Fixpt's types keep them.
pub fn call_shown(v: &'static Cv, all: Sexps, form: &'static Sexp, shown: Str) -> Str {
    let w = {
        let tagcase_ = form;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                if (not(null_p(xs)) && {
                    let tagcase_ = car(xs);
                    match *tagcase_ {
                        Sexp::Sym(n, f2, p2) => {
                            true
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                }) {
                    written_of(sym_name(car(xs)), all)
                } else {
                    nil::<&'static Sexp>()
                }
            }
            _ => {
                let other = tagcase_;
                nil::<&'static Sexp>()
            }
        }
    };
    if (null_p(w) || written_mentions_p(car(w), kayak_rt::heap_cons(str_lit("%found"), kayak_rt::heap_cons(str_lit("->*"), kayak_rt::nil())))) {
        shown
    } else {
        abbrevs_put(shown, abbrevs_in(parse_type(v, kayak_rt::heap_cons(str_lit("%keep-names"), written_tvars(written_binders(v, car(w)))), written_body(car(w)))))
    }
}

/// What `fixpt check` writes of `form`, checked: `v`, the checker's
/// environment after it; `all`, the program's forms.
pub fn form_lines(v: &'static Cv, all: Sexps, form: &'static Sexp) -> Strings {
    if module_def_p(form) {
        nil::<Str>()
    } else if (head_is_p(form, str_lit("define")) || head_is_p(form, str_lit("define*"))) {
        let xs = items(form);
        kayak_rt::heap_cons(bound_line(v, binder_name(second(xs)), if i64_eq(size(xs), 4i64) {
            third(xs)
        } else {
            no_form()
        }, value_effect(v, binder_name(second(xs)), last(xs))), kayak_rt::nil())
    } else if head_is_p(form, str_lit("define-rec")) {
        map(lambda1s(move |g: &'static Sexp| {
            bound_line(v, sym_name(car(items(g))), if i64_eq(size(items(g)), 3i64) {
                second(items(g))
            } else {
                no_form()
            }, str_lit("pure"))
        }), cdr(items(form)))
    } else if head_is_p(form, str_lit("define-datatype")) {
        map(lambda1s(move |g: &'static Sexp| {
            bound_line(v, sym_name(car(items(g))), no_form(), str_lit("pure"))
        }), cdr(cdr(items(form))))
    } else if head_is_p(form, str_lit("define-generative")) {
        let n = binder_name(second(items(form)));
        kayak_rt::heap_cons(bound_line(v, string_append(str_lit("up-"), n), no_form(), str_lit("pure")), kayak_rt::heap_cons(bound_line(v, string_append(str_lit("down-"), n), no_form(), str_lit("pure")), kayak_rt::nil()))
    } else if (head_is_p(form, str_lit("define-type")) || head_is_p(form, str_lit("define-effect")) || head_is_p(form, str_lit("define-convention"))) {
        nil::<Str>()
    } else {
        let tagcase_ = expressions::synth(at(v, str_lit("a top-level expression"), nil::<Str>()), new_state(), form);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                kayak_rt::heap_cons(string_append(call_shown(v, all, form, show_ty(s, t)), string_append(str_lit(" ! "), show_effs(es))), kayak_rt::nil())
            }
        }
    }
}

pub fn lines_checked(v: &'static Cv, all: Sexps, forms: Sexps) -> Strings {
    if null_p(forms) {
        nil::<Str>()
    } else {
        let tagcase_ = check_tops(v, kayak_rt::heap_cons(car(forms), kayak_rt::nil()), nil::<&'static Typed>());
        match *tagcase_ {
            Elab::Elab(v2, found) => {
                onto(form_lines(v2, all, car(forms)), lines_checked(v2, all, cdr(forms)))
            }
        }
    }
}

pub fn lines_text(ls: Strings) -> Str {
    if null_p(ls) {
        str_lit("")
    } else {
        string_append(car(ls), string_append(str_lit("\n"), lines_text(cdr(ls))))
    }
}

pub fn check_command(paths: Strings) -> Int {
    let forms = read_files(paths);
    let empty = cv(nil::<&'static Bind>(), nil::<&'static Dt>(), nil::<&'static Alias>(), nil::<&'static Effdef>(), str_lit("a type"), nil::<Str>(), str_lit("the program"), 0i64, nil::<&'static Fact>(), nil::<Str>(), 0i64);
    let start = cv(nil::<&'static Bind>(), nil::<&'static Dt>(), declare_types(empty, forms, nil::<&'static Alias>()), nil::<&'static Effdef>(), str_lit("a type"), nil::<Str>(), str_lit("the program"), 0i64, nil::<&'static Fact>(), nil::<Str>(), 0i64);
    let types = type_names_free(start, forms);
    let named = {
        let tagcase_ = start;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                cv(bs, datatype_names(start, forms, nil::<&'static Dt>()), als, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let typed = {
        let tagcase_ = named;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                cv(bs, declare_datatypes(named, forms, nil::<&'static Dt>()), als, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let v = with_binds(typed, prim_binds(typed));
    say(lines_text(lines_checked(v, forms, forms)));
    int_lit(0)
}

pub fn main() -> Int {
    let r#as = the::<Strings>(args());
    if (null_p(r#as) || string_eq_p(car(r#as), str_lit("repl"))) {
        (&tasks::repl_x)(history_of(r#as))
    } else if (string_eq_p(car(r#as), str_lit("--keys")) && not(null_p(cdr(r#as))) && null_p(cdr(cdr(r#as)))) {
        (&tasks::scripted_x)(car(cdr(r#as)))
    } else if (string_eq_p(car(r#as), str_lit("--check")) && not(null_p(cdr(r#as)))) {
        check_command(cdr(r#as))
    } else {
        engine_main()
    }
}

